struct Tape {
    struct Node {
        double val;
        double grad;
        int op;
        int a;
        int b;
    };

    std::vector<Node> nodes;

    int constant(double v) {
        nodes.push_back({v, 0.0, 0, -1, -1});
        return (int)nodes.size() - 1;
    }

    int input(double v) {
        nodes.push_back({v, 0.0, 1, -1, -1});
        return (int)nodes.size() - 1;
    }

    int add(int a, int b) {
        double v = nodes[a].val + nodes[b].val;
        nodes.push_back({v, 0.0, 2, a, b});
        return (int)nodes.size() - 1;
    }

    int mul(int a, int b) {
        double v = nodes[a].val * nodes[b].val;
        nodes.push_back({v, 0.0, 3, a, b});
        return (int)nodes.size() - 1;
    }

    int sin_(int a) {
        double v = std::sin(nodes[a].val);
        nodes.push_back({v, 0.0, 4, a, -1});
        return (int)nodes.size() - 1;
    }

    int exp_(int a) {
        double v = std::exp(nodes[a].val);
        nodes.push_back({v, 0.0, 5, a, -1});
        return (int)nodes.size() - 1;
    }

    double value(int node) const {
        return nodes[node].val;
    }

    void add_grad(int node, double g) {
        if (nodes[node].op != 0) {
            nodes[node].grad += g;
        }
    }

    void backward(int root) {
        for (auto &n : nodes) {
            n.grad = 0.0;
        }

        nodes[root].grad = 1.0;

        for (int i = (int)nodes.size() - 1; i >= 0; --i) {
            double g = nodes[i].grad;
            if (g == 0.0) continue;

            switch (nodes[i].op) {
                case 2:
                    add_grad(nodes[i].a, g);
                    add_grad(nodes[i].b, g);
                    break;
                case 3:
                    add_grad(nodes[i].a, g * nodes[nodes[i].b].val);
                    add_grad(nodes[i].b, g * nodes[nodes[i].a].val);
                    break;
                case 4:
                    add_grad(nodes[i].a, g * std::cos(nodes[nodes[i].a].val));
                    break;
                case 5:
                    add_grad(nodes[i].a, g * nodes[i].val);
                    break;
                default:
                    break;
            }
        }
    }

    double grad(int node) const {
        return nodes[node].grad;
    }
};

